sql:
SELECT DISTINCT m.formula
FROM material_entry m
LIMIT 10000;

SELECT DISTINCT m.entry_id, m.formula, m.reduced_formula, m.chemical_system, m.number_of_elements
FROM material_entry m
WHERE EXISTS (
  SELECT 1 FROM composition c1 WHERE c1.entry_id = m.entry_id AND c1.element = 'Ni'
) AND EXISTS (
  SELECT 1 FROM composition c2 WHERE c2.entry_id = m.entry_id AND c2.element = 'Al'
)
LIMIT 10000;

SELECT DISTINCT m.chemical_system
FROM material_entry m
LIMIT 10000;
